WITH flattened_attrs AS (SELECT id, plan, effective_from, tier_limits, tier_prices, SLICE(tier_limits, 1, 2) AS first_two_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT DATE_TRUNC('QUARTER', effective_from) AS quarter_start, plan, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, COUNT(*) AS num_rows, COUNT(CASE WHEN plan = 'starter' THEN 1 END) AS starter_count FROM flattened_attrs GROUP BY GROUPING SETS ((DATE_TRUNC('QUARTER', effective_from), plan), (DATE_TRUNC('QUARTER', effective_from)), ()) ORDER BY quarter_start DESC
